receiving_definitions_and_cited_statemen.night:P5.5:
\begin{theorem}[The full automorphism group]\hypertarget{tag-01QF}{}\label{fam:src:B.4.1}\label{fam:st:B.4.1}\hypertarget{tag-02YQ}{}\label{night:P5.5}\label{stmt:P5.5}
\StatementRecord{night:P5.5}{proved}{02YQ}{the definitions and constructions stated in the proof}

For every admissible twist of the $(3,4)$ construction,
\[
 \operatorname{Aut}(X_c)=\mathbb C/\mathbb Z\simeq\mathbb C^*.
\]
The parameter $a\bmod\mathbb Z$ acts by $\zeta\mapsto\zeta+ae$,
where $e=\Pi_c\widehat\delta$. The exponential group isomorphism
is $a\bmod\mathbb Z\mapsto e^{2\pi ia}$.
\end{theorem}

receiving_definitions_and_cited_statemen.night:P5.6:
\begin{theorem}[Integral torsor classes and the parameter period]\hypertarget{tag-02YR}{}\label{night:P5.6}\label{stmt:P5.6}
\StatementRecord{night:P5.6}{proved}{02YR}{the definitions and constructions stated in the proof}

For fixed admissible twist data, $X_c\simeq X_{c'}$ precisely when
$c-c'\in2\mathbb Z$.  This fixes the integral period of $c$; the
construction still permits an additive choice of $\beta^{\rm part}$.
\end{theorem}

primary_DGKX_definitions.period_data_statement:
\begin{proposition}
\label{prop:period-data-existence}
There are holomorphic functions
\[
 \tau,\mu,\beta_0:U\longrightarrow\C,
 \qquad \Im\tau>0,
\]
and holomorphic matrices $R_g:U\to\GL(2,\C)$ satisfying
\begin{align}
 R_{gh}(z)&=R_g(hz)R_h(z),
 \label{eq:R-cocycle}\\
 \Omega_a(gz)&=R_g(z)\Omega_a(z)A(g)^{-1}
 \label{eq:period-equivariance}
\end{align}
for every $g,h\in\Gamma$ and every $a\in\C$, where
\begin{equation}
\label{eq:period-matrix}
 \Omega_a(z)=
 \begin{pmatrix}
 6\mu(z)&\tau(z)&1&0\\
 \beta_0(z)+a&\mu(z)&0&1
 \end{pmatrix}.
\end{equation}
The equations for all $a$ follow from those for $a=0$: the right block
defining $R_g$ is unchanged when a constant is added to $\beta_0$,
and $\gamma A(g)^{-1}=\gamma$.
Consequently the same equations hold for every $a\in\C$. The
real-lattice condition is imposed separately in
\cref{prop:admissible-half-plane}. Together with
\eqref{eq:R-cocycle} and the representation law for $A$, this
equivariance makes the orbifold descent an honest group action.

Set
\begin{equation}
\label{eq:D-a}
 \mathscr D_a(z)=\Im(\beta_0(z)+a)
        -\frac{6(\Im\mu(z))^2}{\Im\tau(z)}.
\end{equation}
The function $\mathscr D_0$ is
$\Gamma$-invariant, descends to $B\setminus\{p_0\}$, and tends to $-\infty$
as $p_0$ is approached.  Its descended function is continuous at the two
finite orbifold points; together with the cusp limit, this makes
$\mathscr D_0$ bounded above.
\end{proposition}
